import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <cuda_pipeline.h>
#include <cmath>
using namespace nvcuda;
#define THREADS 256
#define BR 64
#define BK 64
#define BN 64
#define SKEW 8
#define LDK (BK + SKEW)
#define LDV (BN + SKEW)
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define ASYNC_COPY16(dst, src) __pipeline_memcpy_async((dst), (src), 16)
#define ASYNC_COMMIT() __pipeline_commit()
#define ASYNC_WAIT(n) __pipeline_wait_prior(n)
#else
#define ASYNC_COPY16(dst, src) (*reinterpret_cast<uint4*>(dst) = *reinterpret_cast<const uint4*>(src))
#define ASYNC_COMMIT() do {} while (0)
#define ASYNC_WAIT(n) do {} while (0)
#endif
// Tensor-core SDPA: one block handles BR query rows of one (batch, head).
// Both phases (Q*K^T and P*V) use WMMA 16x16x16 fragments on fp16 inputs.
template <int NJ>
__global__ void __launch_bounds__(THREADS) sdpa_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int S, int D,
    float scale
) {
    const int bh = blockIdx.y;
    const int row0 = blockIdx.x * BR;
    const size_t base = (size_t)bh * (size_t)S * (size_t)D;
    const __half* q = Q + base;
    const __half* k = K + base;
    const __half* v = V + base;
    __half* o = O + base;
    extern __shared__ __align__(16) __half smem[];
    const int PSTR = S + SKEW;
    const int RH = S >> 1;                // rows per pipelined V chunk
    __half* sQb = smem;                   // phase A: 2 x BR x LDK (double-buffered Q tiles)
    __half* sKb = sQb + 2 * BR * LDK;     // phase A: 2 x S  x LDK (double-buffered K tiles)
    __half* sS = sKb + (size_t)S * LDK;   // BR x S scaled scores (aliases K stage 1)
    __half* sP = smem;                    // BR x PSTR (aliased, phase B)
    __half* sVb = sP + BR * PSTR;         // 2 x RH x LDV (aliased, phase B)
    const int tid = threadIdx.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int wr = warp & 3;   // 4 row groups of 16 -> 64 rows
    const int wc = warp >> 2;  // 2 col groups
    const int WCOLS = NJ * 16; // columns per warp in phase A (= S/2)
    // Phase A: scores = (Q * K^T) * scale, tiled over the head dimension.
    // Double-buffered cp.async pipeline: next Q/K tile loads while MMA runs.
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[NJ];
    #pragma unroll
    for (int u = 0; u < NJ; ++u) wmma::fill_fragment(acc[u], 0.0f);
    const int NT = D / BK;
    const int WQ = BK >> 3;
    const uint4* qg = reinterpret_cast<const uint4*>(q) + (size_t)row0 * (size_t)(D >> 3);
    const uint4* kg = reinterpret_cast<const uint4*>(k);
    auto stage_qk = [&](int t, int buf) {
        __half* sQ = sQb + buf * BR * LDK;
        __half* sK = sKb + (size_t)buf * (size_t)S * LDK;
        for (int idx = tid; idx < BR * WQ; idx += THREADS) {
            const int rr = idx / WQ;
            const int cc = idx - rr * WQ;
            ASYNC_COPY16(reinterpret_cast<uint4*>(sQ) + rr * (LDK >> 3) + cc,
                         qg + (size_t)rr * (size_t)(D >> 3) + t * WQ + cc);
        }
        for (int idx = tid; idx < S * WQ; idx += THREADS) {
            const int rr = idx / WQ;
            const int cc = idx - rr * WQ;
            ASYNC_COPY16(reinterpret_cast<uint4*>(sK) + rr * (LDK >> 3) + cc,
                         kg + (size_t)rr * (size_t)(D >> 3) + t * WQ + cc);
        }
        ASYNC_COMMIT();
    };
    stage_qk(0, 0);
    if (NT > 1) stage_qk(1, 1);
    for (int t = 0; t < NT; ++t) {
        const int buf = t & 1;
        ASYNC_WAIT(t + 1 < NT ? 1 : 0);
        __syncthreads();
        const __half* sQ = sQb + buf * BR * LDK;
        const __half* sK = sKb + (size_t)buf * (size_t)S * LDK;
        #pragma unroll
        for (int kk = 0; kk < BK; kk += 16) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, sQ + wr * 16 * LDK + kk, LDK);
            #pragma unroll
            for (int j = 0; j < NJ; ++j) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> b;
                wmma::load_matrix_sync(b, sK + (wc * WCOLS + j * 16) * LDK + kk, LDK);
                wmma::mma_sync(acc[j], a, b, acc[j]);
            }
        }
        __syncthreads();
        if (t + 2 < NT) stage_qk(t + 2, buf);
    }
    // Scale and stage scores (fp16) in shared memory.
    #pragma unroll
    for (int j = 0; j < NJ; ++j) {
        wmma::fragment<wmma::accumulator, 16, 16, 16, __half> h;
        #pragma unroll
        for (int e = 0; e < h.num_elements; ++e) h.x[e] = __float2half_rn(acc[j].x[e] * scale);
        wmma::store_matrix_sync(sS + wr * 16 * S + wc * WCOLS + j * 16, h, S, wmma::mem_row_major);
    }
    __syncthreads();
    // Softmax: one warp cooperates on each query row.
    for (int r = warp; r < BR; r += (THREADS >> 5)) {
        const __half* srow = sS + r * S;
        float mx = -INFINITY;
        #pragma unroll
        for (int i = 0; i < NJ; ++i) mx = fmaxf(mx, __half2float(srow[lane + (i << 5)]));
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            mx = fmaxf(mx, __shfl_xor_sync(0xffffffffu, mx, off));
        float ev[NJ];
        float sum = 0.0f;
        #pragma unroll
        for (int i = 0; i < NJ; ++i) {
            ev[i] = exp2f(__half2float(srow[lane + (i << 5)]) - mx);
            sum += ev[i];
        }
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            sum += __shfl_xor_sync(0xffffffffu, sum, off);
        const float inv_sum = 1.0f / sum;
        __half* prow = sP + r * PSTR;
        #pragma unroll
        for (int i = 0; i < NJ; ++i) prow[lane + (i << 5)] = __float2half_rn(ev[i] * inv_sum);
    }
    __syncthreads();
    // Phase B: O = P * V, tiled over the head dimension.
    // V rows stream through a double-buffered cp.async pipeline (RH rows per chunk).
    const int NC = (D / BN) * 2;
    const int WV = BN >> 3;
    const uint4* vg = reinterpret_cast<const uint4*>(v);
    auto stage_v = [&](int c, int buf) {
        const int n0 = (c >> 1) * BN;
        const int r0 = (c & 1) * RH;
        __half* sV = sVb + (size_t)buf * (size_t)RH * LDV;
        for (int idx = tid; idx < RH * WV; idx += THREADS) {
            const int rr = idx / WV;
            const int cc = idx - rr * WV;
            ASYNC_COPY16(reinterpret_cast<uint4*>(sV) + rr * (LDV >> 3) + cc,
                         vg + (size_t)(r0 + rr) * (size_t)(D >> 3) + (n0 >> 3) + cc);
        }
        ASYNC_COMMIT();
    };
    stage_v(0, 0);
    if (NC > 1) stage_v(1, 1);
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc[2];
    wmma::fill_fragment(oacc[0], 0.0f);
    wmma::fill_fragment(oacc[1], 0.0f);
    for (int c = 0; c < NC; ++c) {
        const int buf = c & 1;
        ASYNC_WAIT(c + 1 < NC ? 1 : 0);
        __syncthreads();
        const int r0 = (c & 1) * RH;
        const __half* sV = sVb + (size_t)buf * (size_t)RH * LDV;
        for (int k0 = 0; k0 < RH; k0 += 16) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, sP + wr * 16 * PSTR + r0 + k0, PSTR);
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b0;
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b1;
            wmma::load_matrix_sync(b0, sV + k0 * LDV + wc * 32, LDV);
            wmma::load_matrix_sync(b1, sV + k0 * LDV + wc * 32 + 16, LDV);
            wmma::mma_sync(oacc[0], a, b0, oacc[0]);
            wmma::mma_sync(oacc[1], a, b1, oacc[1]);
        }
        if (c & 1) {
            const int n0 = (c >> 1) * BN;
            wmma::fragment<wmma::accumulator, 16, 16, 16, __half> h0, h1;
            #pragma unroll
            for (int e = 0; e < h0.num_elements; ++e) {
                h0.x[e] = __float2half_rn(oacc[0].x[e]);
                h1.x[e] = __float2half_rn(oacc[1].x[e]);
            }
            __half* optr = o + (size_t)(row0 + wr * 16) * (size_t)D + n0 + wc * 32;
            wmma::store_matrix_sync(optr, h0, D, wmma::mem_row_major);
            wmma::store_matrix_sync(optr + 16, h1, D, wmma::mem_row_major);
            wmma::fill_fragment(oacc[0], 0.0f);
            wmma::fill_fragment(oacc[1], 0.0f);
        }
        __syncthreads();
        if (c + 2 < NC) stage_v(c + 2, buf);
    }
}
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Q, K, V must be float16");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(),
                "Q, K, V must be contiguous");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have the same shape");
    const int B = (int)Q.size(0);
    const int H = (int)Q.size(1);
    const int S = (int)Q.size(2);
    const int D = (int)Q.size(3);
    TORCH_CHECK((S % BR) == 0 && S <= 256, "sequence_length must be a multiple of 64 and <= 256");
    TORCH_CHECK((D % BK) == 0, "embedding_dimension must be a multiple of 64");
    auto O = torch::empty_like(Q);
    const float scale = (float)(1.44269504088896340736 / std::sqrt((float)D));
    const size_t smemA = (2 * ((size_t)BR + (size_t)S) * (size_t)LDK) * sizeof(__half);
    const size_t smemB = ((size_t)BR * (size_t)(S + SKEW) + (size_t)S * (size_t)LDV) * sizeof(__half);
    const size_t shmem_bytes = smemA > smemB ? smemA : smemB;
    static bool configured = false;
    if (!configured) {
        cudaFuncSetAttribute((const void*)sdpa_kernel<2>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        cudaFuncSetAttribute((const void*)sdpa_kernel<4>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        cudaFuncSetAttribute((const void*)sdpa_kernel<6>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        cudaFuncSetAttribute((const void*)sdpa_kernel<8>, cudaFuncAttributeMaxDynamicSharedMemorySize, 96 * 1024);
        configured = true;
    }
    const dim3 grid(S / BR, B * H);
    auto stream = at::cuda::getCurrentCUDAStream();
    const __half* qp = reinterpret_cast<const __half*>(Q.data_ptr<at::Half>());
    const __half* kp = reinterpret_cast<const __half*>(K.data_ptr<at::Half>());
    const __half* vp = reinterpret_cast<const __half*>(V.data_ptr<at::Half>());
    __half* op = reinterpret_cast<__half*>(O.data_ptr<at::Half>());
    switch (S / 32) {
        case 2: sdpa_kernel<2><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        case 4: sdpa_kernel<4><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        case 6: sdpa_kernel<6><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        case 8: sdpa_kernel<8><<<grid, THREADS, shmem_bytes, stream>>>(qp, kp, vp, op, B, H, S, D, scale); break;
        default: TORCH_CHECK(false, "unsupported sequence_length");
    }
    return O;
}
'''
cpp_src = "torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);"
_mod = load_inline(
    name="custom_sdpa_single_kernel",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sdpa_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _mod.sdpa_forward(Q, K, V)

